  1: package providers
  2: 
  3: import (
  4: 	"encoding/json"
  5: 	"fmt"
  6: 	"net/http"
  7: 	"net/url"
  8: 	"strings"
  9: 
 10: 	"github.com/ByteTrue/commit-now-myfriend/internal/config"
 11: 	runtimex "github.com/ByteTrue/commit-now-myfriend/internal/runtime"
 12: )
 13: 
 14: type ToolCallProviderOptions struct {
 15: 	Config       ProviderConfig
 16: 	Instructions string
 17: 	Input        string
 18: 	Tools        []runtimex.ToolName
 19: }
 20: 
 21: type httpToolCallProvider struct {
 22: 	cfg                ProviderConfig
 23: 	adapter            ToolProtocolAdapter
 24: 	client             HTTPDoer
 25: 	instructions       string
 26: 	input              string
 27: 	tools              []runtimex.ToolName
 28: 	previousResponseID string
 29: 	chatMessages       []map[string]any
 30: 	anthropicMessages  []map[string]any
 31: 	geminiContents     []map[string]any
 32: 	responsesInput     []map[string]any
 33: 	turnCount          int
 34: }
 35: 
 36: func CreateToolCallProvider(options ToolCallProviderOptions) (runtimex.ToolCallProvider, error) {
 37: 	adapter, err := CreateToolProtocolAdapter(options.Config)
 38: 	if err != nil {
 39: 		return nil, err
 40: 	}
 41: 	if err := validateProviderConfig(options.Config, options.Config.Provider == config.ProviderOpenAICompatible); err != nil {
 42: 		return nil, err
 43: 	}
 44: 	return &httpToolCallProvider{
 45: 		cfg:          options.Config,
 46: 		adapter:      adapter,
 47: 		client:       resolveHTTPClient(options.Config),
 48: 		instructions: options.Instructions,
 49: 		input:        options.Input,
 50: 		tools:        append([]runtimex.ToolName{}, options.Tools...),
 51: 	}, nil
 52: }
 53: 
 54: func (p *httpToolCallProvider) NextToolCalls(results []runtimex.ToolCallResult) (runtimex.ProviderTurn, error) {
 55: 	payload, err := p.requestPayload(results)
 56: 	if err != nil {
 57: 		return runtimex.ProviderTurn{}, err
 58: 	}
 59: 	request, err := p.newRequest(payload)
 60: 	if err != nil {
 61: 		return runtimex.ProviderTurn{}, err
 62: 	}
 63: 	response, err := p.client.Do(request)
 64: 	if err != nil {
 65: 		return runtimex.ProviderTurn{}, err
 66: 	}
 67: 	body, err := readResponseBody(response)
 68: 	if err != nil {
 69: 		return runtimex.ProviderTurn{}, err
 70: 	}
 71: 	if response.StatusCode < 200 || response.StatusCode >= 300 {
 72: 		return runtimex.ProviderTurn{}, fmt.Errorf("provider request failed with http %d", response.StatusCode)
 73: 	}
 74: 	p.captureProviderState(body)
 75: 	p.turnCount++
 76: 	turn, err := p.adapter.ParseTurn(body)
 77: 	if err != nil {
 78: 		return runtimex.ProviderTurn{}, fmt.Errorf("provider response parse error: %w", err)
 79: 	}
 80: 	return turn, nil
 81: }
 82: 
 83: func (p *httpToolCallProvider) requestPayload(results []runtimex.ToolCallResult) (map[string]any, error) {
 84: 	if p.turnCount == 0 && len(results) == 0 {
 85: 		return p.initialPayload()
 86: 	}
 87: 	if len(results) == 1 && results[0].Name == runtimex.ToolName("__reminder__") {
 88: 		return p.reminderPayload(results[0])
 89: 	}
 90: 	fragment, err := p.adapter.BuildToolResultPayload(results)
 91: 	if err != nil {
 92: 		return nil, err
 93: 	}
 94: 	var payload map[string]any
 95: 	if err := json.Unmarshal(fragment, &payload); err != nil {
 96: 		return nil, err
 97: 	}
 98: 	p.applyContinuationPayload(payload)
 99: 	return payload, nil
100: }
101: 
102: func (p *httpToolCallProvider) reminderPayload(reminder runtimex.ToolCallResult) (map[string]any, error) {
103: 	message := "Reminder: please call one of the available tools to continue."
104: 	if reminder.Error != nil && reminder.Error.Message != "" {
105: 		message = reminder.Error.Message
106: 	}
107: 	payload := map[string]any{}
108: 	fragment, err := p.adapter.BuildInitialRequest(p.tools)
109: 	if err == nil {
110: 		var toolsPayload map[string]any
111: 		if err := json.Unmarshal(fragment, &toolsPayload); err == nil {
112: 			if t, ok := toolsPayload["tools"]; ok {
113: 				payload["tools"] = t
114: 			}
115: 		}
116: 	}
117: 	switch p.cfg.Provider {
118: 	case config.ProviderOpenAIResponses:
119: 		payload["model"] = p.cfg.Model
120: 		payload["instructions"] = p.instructions
121: 		p.responsesInput = append(p.responsesInput, map[string]any{"role": "user", "content": message})
122: 		payload["input"] = p.responsesInput
123: 		payload["max_output_tokens"] = resolveMaxOutputTokens(p.cfg)
124: 		payload["tool_choice"] = "auto"
125: 	case config.ProviderOpenAICompatible:
126: 		payload["model"] = p.cfg.Model
127: 		p.chatMessages = append(p.chatMessages, map[string]any{"role": "user", "content": message})
128: 		payload["messages"] = p.chatMessages
129: 		payload["temperature"] = 0.2
130: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
131: 		payload["tool_choice"] = "required"
132: 	case config.ProviderAnthropic:
133: 		payload["model"] = p.cfg.Model
134: 		payload["system"] = p.instructions
135: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
136: 		p.anthropicMessages = append(p.anthropicMessages, map[string]any{"role": "user", "content": message})
137: 		payload["messages"] = p.anthropicMessages
138: 		payload["tool_choice"] = map[string]any{"type": "any"}
139: 	case config.ProviderGoogleGemini:
140: 		p.geminiContents = append(p.geminiContents, map[string]any{"role": "user", "parts": []map[string]string{{"text": message}}})
141: 		payload["contents"] = p.geminiContents
142: 		payload["generationConfig"] = map[string]any{"temperature": 0.2, "maxOutputTokens": resolveMaxOutputTokens(p.cfg)}
143: 	}
144: 	return payload, nil
145: }
146: 
147: func (p *httpToolCallProvider) initialPayload() (map[string]any, error) {
148: 	fragment, err := p.adapter.BuildInitialRequest(p.tools)
149: 	if err != nil {
150: 		return nil, err
151: 	}
152: 	var payload map[string]any
153: 	if err := json.Unmarshal(fragment, &payload); err != nil {
154: 		return nil, err
155: 	}
156: 	switch p.cfg.Provider {
157: 	case config.ProviderOpenAIResponses:
158: 		payload["model"] = p.cfg.Model
159: 		payload["instructions"] = p.instructions
160: 		p.responsesInput = []map[string]any{{"role": "user", "content": p.input}}
161: 		payload["input"] = p.responsesInput
162: 		payload["temperature"] = 0.2
163: 		payload["max_output_tokens"] = resolveMaxOutputTokens(p.cfg)
164: 		payload["tool_choice"] = "auto"
165: 	case config.ProviderOpenAICompatible:
166: 		payload["model"] = p.cfg.Model
167: 		p.chatMessages = []map[string]any{{"role": "system", "content": p.instructions}, {"role": "user", "content": p.input}}
168: 		payload["messages"] = p.chatMessages
169: 		payload["temperature"] = 0.2
170: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
171: 		payload["tool_choice"] = "required"
172: 	case config.ProviderAnthropic:
173: 		payload["model"] = p.cfg.Model
174: 		payload["system"] = p.instructions
175: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
176: 		p.anthropicMessages = []map[string]any{{"role": "user", "content": p.input}}
177: 		payload["messages"] = p.anthropicMessages
178: 		payload["tool_choice"] = map[string]any{"type": "any"}
179: 	case config.ProviderGoogleGemini:
180: 		payload["systemInstruction"] = map[string]any{"parts": []map[string]string{{"text": p.instructions}}}
181: 		p.geminiContents = []map[string]any{{"role": "user", "parts": []map[string]string{{"text": p.input}}}}
182: 		payload["contents"] = p.geminiContents
183: 		payload["generationConfig"] = map[string]any{"temperature": 0.2, "maxOutputTokens": resolveMaxOutputTokens(p.cfg)}
184: 	}
185: 	return payload, nil
186: }
187: 
188: func (p *httpToolCallProvider) applyContinuationPayload(payload map[string]any) {
189: 	if payload["tools"] == nil {
190: 		fragment, err := p.adapter.BuildInitialRequest(p.tools)
191: 		if err == nil {
192: 			var toolsPayload map[string]any
193: 			if err := json.Unmarshal(fragment, &toolsPayload); err == nil {
194: 				if t, ok := toolsPayload["tools"]; ok {
195: 					payload["tools"] = t
196: 				}
197: 			}
198: 		}
199: 	}
200: 	switch p.cfg.Provider {
201: 	case config.ProviderOpenAIResponses:
202: 		payload["model"] = p.cfg.Model
203: 		payload["instructions"] = p.instructions
204: 		newInputs, _ := payload["input"].([]any)
205: 		for _, item := range newInputs {
206: 			if m, ok := item.(map[string]any); ok {
207: 				p.responsesInput = append(p.responsesInput, m)
208: 			}
209: 		}
210: 		payload["input"] = p.responsesInput
211: 		payload["max_output_tokens"] = resolveMaxOutputTokens(p.cfg)
212: 		payload["tool_choice"] = "auto"
213: 	case config.ProviderOpenAICompatible:
214: 		payload["model"] = p.cfg.Model
215: 		toolMessages, _ := payload["messages"].([]any)
216: 		p.chatMessages = append(p.chatMessages, normalizeToolMessages(toolMessages)...)
217: 		payload["messages"] = p.chatMessages
218: 		payload["tool_choice"] = "required"
219: 	case config.ProviderAnthropic:
220: 		payload["model"] = p.cfg.Model
221: 		payload["system"] = p.instructions
222: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
223: 		toolMessages, _ := payload["messages"].([]any)
224: 		p.anthropicMessages = append(p.anthropicMessages, normalizeToolMessages(toolMessages)...)
225: 		payload["messages"] = p.anthropicMessages
226: 		payload["tool_choice"] = map[string]any{"type": "any"}
227: 	case config.ProviderGoogleGemini:
228: 		contents, _ := payload["contents"].([]any)
229: 		p.geminiContents = append(p.geminiContents, normalizeToolMessages(contents)...)
230: 		payload["contents"] = p.geminiContents
231: 		payload["generationConfig"] = map[string]any{"temperature": 0.2, "maxOutputTokens": resolveMaxOutputTokens(p.cfg)}
232: 	}
233: }
234: 
235: func (p *httpToolCallProvider) newRequest(payload map[string]any) (*http.Request, error) {
236: 	body, err := json.Marshal(payload)
237: 	if err != nil {
238: 		return nil, err
239: 	}
240: 	endpoint := p.endpoint()
241: 	request, err := newJSONRequest(http.MethodPost, endpoint, body)
242: 	if err != nil {
243: 		return nil, err
244: 	}
245: 	switch p.cfg.Provider {
246: 	case config.ProviderOpenAIResponses, config.ProviderOpenAICompatible:
247: 		request.Header.Set("Authorization", "Bearer "+*p.cfg.APIKey)
248: 	case config.ProviderAnthropic:
249: 		request.Header.Set("x-api-key", *p.cfg.APIKey)
250: 		request.Header.Set("anthropic-version", "2023-06-01")
251: 	}
252: 	applyUserAgent(request, p.cfg)
253: 	return request, nil
254: }
255: 
256: func (p *httpToolCallProvider) endpoint() string {
257: 	switch p.cfg.Provider {
258: 	case config.ProviderOpenAICompatible:
259: 		return joinURL(*p.cfg.BaseURL, "/chat/completions")
260: 	case config.ProviderOpenAIResponses:
261: 		return joinURL(optionalStringOrDefault(p.cfg.BaseURL, defaultOpenAIBaseURL), "/responses")
262: 	case config.ProviderAnthropic:
263: 		return joinURL(optionalStringOrDefault(p.cfg.BaseURL, defaultAnthropicBaseURL), "/messages")
264: 	case config.ProviderGoogleGemini:
265: 		baseURL := optionalStringOrDefault(p.cfg.BaseURL, defaultGeminiBaseURL)
266: 		return joinURL(baseURL, "/v1beta/models/"+url.PathEscape(p.cfg.Model)+":generateContent") + "?key=" + url.QueryEscape(*p.cfg.APIKey)
267: 	default:
268: 		return ""
269: 	}
270: }
271: 
272: func (p *httpToolCallProvider) captureProviderState(body []byte) {
273: 	switch p.cfg.Provider {
274: 	case config.ProviderOpenAIResponses:
275: 		p.captureOpenAIResponsesID(body)
276: 	case config.ProviderOpenAICompatible:
277: 		p.captureOpenAICompatibleAssistant(body)
278: 	case config.ProviderAnthropic:
279: 		p.captureAnthropicAssistant(body)
280: 	case config.ProviderGoogleGemini:
281: 		p.captureGeminiModelContent(body)
282: 	}
283: }
284: 
285: func (p *httpToolCallProvider) captureOpenAIResponsesID(body []byte) {
286: 	var response struct {
287: 		ID     string           `json:"id"`
288: 		Output []map[string]any `json:"output"`
289: 	}
290: 	if err := json.Unmarshal(body, &response); err != nil {
291: 		return
292: 	}
293: 	if strings.TrimSpace(response.ID) != "" {
294: 		p.previousResponseID = response.ID
295: 	}
296: 	for _, item := range response.Output {
297: 		t, _ := item["type"].(string)
298: 		if t == "function_call" || t == "message" || t == "reasoning" {
299: 			p.responsesInput = append(p.responsesInput, item)
300: 		}
301: 	}
302: }
303: 
304: func (p *httpToolCallProvider) captureOpenAICompatibleAssistant(body []byte) {
305: 	var response struct {
306: 		Choices []struct {
307: 			Message map[string]any `json:"message"`
308: 		} `json:"choices"`
309: 	}
310: 	if err := json.Unmarshal(body, &response); err != nil || len(response.Choices) == 0 || len(response.Choices[0].Message) == 0 {
311: 		return
312: 	}
313: 	p.chatMessages = append(p.chatMessages, response.Choices[0].Message)
314: }
315: 
316: func (p *httpToolCallProvider) captureAnthropicAssistant(body []byte) {
317: 	var response struct {
318: 		Content []map[string]any `json:"content"`
319: 	}
320: 	if err := json.Unmarshal(body, &response); err != nil || len(response.Content) == 0 {
321: 		return
322: 	}
323: 	p.anthropicMessages = append(p.anthropicMessages, map[string]any{"role": "assistant", "content": response.Content})
324: }
325: 
326: func (p *httpToolCallProvider) captureGeminiModelContent(body []byte) {
327: 	var response struct {
328: 		Candidates []struct {
329: 			Content map[string]any `json:"content"`
330: 		} `json:"candidates"`
331: 	}
332: 	if err := json.Unmarshal(body, &response); err != nil || len(response.Candidates) == 0 || len(response.Candidates[0].Content) == 0 {
333: 		return
334: 	}
335: 	content := response.Candidates[0].Content
336: 	if _, ok := content["role"]; !ok {
337: 		content["role"] = "model"
338: 	}
339: 	p.geminiContents = append(p.geminiContents, content)
340: }
341: 
342: func normalizeToolMessages(values []any) []map[string]any {
343: 	messages := make([]map[string]any, 0, len(values))
344: 	for _, value := range values {
345: 		message, ok := value.(map[string]any)
346: 		if ok {
347: 			messages = append(messages, message)
348: 		}
349: 	}
350: 	return messages
351: }

