282: func parseToolArgumentsString(raw string) (map[string]any, error) {
283: 	if strings.TrimSpace(raw) == "" {
284: 		return map[string]any{}, nil
285: 	}
286: 	var arguments map[string]any
287: 	if err := json.Unmarshal([]byte(raw), &arguments); err != nil {
288: 		return nil, fmt.Errorf("provider returned malformed tool arguments: %w", err)
289: 	}
290: 	return arguments, nil
291: }
292: 
293: func encodeToolResult(result runtimex.ToolCallResult) (string, error) {
294: 	object, err := toolResultMap(result)
295: 	if err != nil {
296: 		return "", err
297: 	}
298: 	buffer, err := json.Marshal(object)
299: 	if err != nil {
300: 		return "", err
301: 	}
302: 	return string(buffer), nil
303: }
304: 
305: func toolResultObject(result runtimex.ToolCallResult) (string, error) {
306: 	return encodeToolResult(result)
307: }
308: 
309: func toolResultMap(result runtimex.ToolCallResult) (map[string]any, error) {
310: 	object := map[string]any{"ok": result.OK}
311: 	if result.OK {
312: 		object["result"] = result.Result
313: 	} else if result.Error != nil {
314: 		object["error"] = result.Error
315: 	} else {
316: 		object["error"] = map[string]any{"code": "tool_failed", "message": "tool call failed"}
317: 	}
318: 	return object, nil
319: }
320: 
321: func cloneArguments(arguments map[string]any) map[string]any {
322: 	cloned := make(map[string]any, len(arguments))
323: 	for key, value := range arguments {
324: 		cloned[key] = value
325: 	}
326: 	return cloned
327: }

