254: func openAIFunctionTools(tools []runtimex.ToolName) []map[string]any {
255: 	items := make([]map[string]any, 0, len(tools))
256: 	for _, tool := range tools {
257: 		items = append(items, map[string]any{
258: 			"type": "function",
259: 			"function": map[string]any{
