201: func parseGeminiTurn(payload []byte) (runtimex.ProviderTurn, error) {
202: 	var response struct {
203: 		Candidates []struct {
204: 			Content struct {
205: 				Parts []struct {
206: 					FunctionCall *struct {
207: 						Name string         `json:"name"`
208: 						Args map[string]any `json:"args"`
209: 					} `json:"functionCall"`
210: 				} `json:"parts"`
211: 			} `json:"content"`
212: 		} `json:"candidates"`
213: 	}
214: 	if err := json.Unmarshal(payload, &response); err != nil {
215: 		return runtimex.ProviderTurn{}, err
216: 	}
217: 	calls := make([]runtimex.ToolCallRequest, 0)
218: 	for _, candidate := range response.Candidates {
219: 		for _, part := range candidate.Content.Parts {
220: 			if part.FunctionCall == nil {
221: 				continue
222: 			}
223: 			name := part.FunctionCall.Name
224: 			calls = append(calls, runtimex.ToolCallRequest{ID: name, Name: runtimex.ToolName(name), Arguments: cloneArguments(part.FunctionCall.Args)})
225: 		}
226: 	}
227: 	return runtimex.ProviderTurn{ToolCalls: calls}, nil
228: }
