282: func parseToolArgumentsString(raw string) (map[string]any, error) {
283: 	if strings.TrimSpace(raw) == "" {
284: 		return map[string]any{}, nil
285: 	}
286: 	var arguments map[string]any
287: 	if err := json.Unmarshal([]byte(raw), &arguments); err != nil {
288: 		return nil, fmt.Errorf("provider returned malformed tool arguments: %w", err)
289: 	}
290: 	return arguments, nil
291: }
