172: 			continue
173: 		}
174: 		if arg == "--help" || arg == "-h" {
175: 			return "cnm help"
176: 		}
177: 		if arg == "--version" || arg == "-version" {
178: 			return "cnm version"
179: 		}
180: 		break
181: 	}
182: 	command, _ := resolveCommand(args)
183: 	switch command {
184: 	case "":
185: 		return "cnm"
186: 	case "auto":
187: 		return "cnm auto"
188: 	case "init":
189: 		return "cnm init"
