250: func runConfigCommand(args []string, runtime Runtime) int {
251: 	if len(args) == 0 && runtime.IsTTY {
252: 		return runConfigPanel(runtime)
253: 	}
254: 	return commands.RunConfig(args, commands.ConfigRuntime{
255: 		CWD:         runtime.CWD,
256: 		Env:         runtime.Env,
257: 		Stdout:      runtime.Stdout,
