 814: func interactiveRepairDomainTools(runtime Runtime, scope gitpkg.CommitScope, eligiblePaths []string) runtimex.DomainToolSet {
 815: 	allowed := allowedPathSet(eligiblePaths)
 816: 	return runtimex.NewDomainToolSet(runtimex.DomainToolSetOptions{
 817: 		InspectCommitScope: func() (gitpkg.CommitScope, error) {
 818: 			return gitpkg.InspectCommitScope(gitpkg.CommitScopeOptions{CWD: runtime.CWD, Env: runtime.Env, IncludeUntracked: scope.IncludesUntracked, StagedOnly: scope.StagedOnly, DiffOnly: scope.ContextPolicy.Mode == gitpkg.ContextPolicyModeDiffOnly, Pathspecs: scope.Pathspecs})
 819: 		},
 820: 		GetDiff: func() (runtimex.DiffResult, error) {
 821: 			result, err := gitpkg.DefaultCommandRunner(runtime.CWD, scopedDiffArgs(eligiblePaths), runtime.Env)
 822: 			if err != nil {
 823: 				return runtimex.DiffResult{}, err
 824: 			}
 825: 			if result.ExitCode != 0 {
 826: 				return runtimex.DiffResult{}, fmt.Errorf("%s", firstNonEmptyString(result.Stderr, result.Stdout, "git diff failed"))
