 814: func interactiveRepairDomainTools(runtime Runtime, scope gitpkg.CommitScope, eligiblePaths []string) runtimex.DomainToolSet {
 815: 	allowed := allowedPathSet(eligiblePaths)
 816: 	return runtimex.NewDomainToolSet(runtimex.DomainToolSetOptions{
 817: 		InspectCommitScope: func() (gitpkg.CommitScope, error) {
 818: 			return gitpkg.InspectCommitScope(gitpkg.CommitScopeOptions{CWD: runtime.CWD, Env: runtime.Env, IncludeUntracked: scope.IncludesUntracked, StagedOnly: scope.StagedOnly, DiffOnly: scope.ContextPolicy.Mode == gitpkg.ContextPolicyModeDiffOnly, Pathspecs: scope.Pathspecs})
 819: 		},
 820: 		GetDiff: func() (runtimex.DiffResult, error) {
 821: 			result, err := gitpkg.DefaultCommandRunner(runtime.CWD, scopedDiffArgs(eligiblePaths), runtime.Env)
 822: 			if err != nil {
 823: 				return runtimex.DiffResult{}, err
 824: 			}
 825: 			if result.ExitCode != 0 {
 826: 				return runtimex.DiffResult{}, fmt.Errorf("%s", firstNonEmptyString(result.Stderr, result.Stdout, "git diff failed"))
 827: 			}
 828: 			return runtimex.DiffResult{Content: result.Stdout, Bytes: len([]byte(result.Stdout))}, nil
 829: 		},
 830: 		ReadFile: func(path string) (runtimex.FileReadResult, error) {
 831: 			relativePath, err := requireAllowedRepairPath(path, allowed)
 832: 			if err != nil {
 833: 				return runtimex.FileReadResult{}, err
 834: 			}
 835: 			absolutePath, err := repoFilePath(runtime.CWD, relativePath)
 836: 			if err != nil {
 837: 				return runtimex.FileReadResult{}, err
 838: 			}
 839: 			content, err := os.ReadFile(absolutePath)
 840: 			if err != nil {
 841: 				return runtimex.FileReadResult{}, err
 842: 			}
 843: 			return runtimex.FileReadResult{Path: relativePath, Content: string(content), Bytes: len(content)}, nil
 844: 		},
 845: 		PreviewCommit: func(input runtimex.CommitPreviewInput) (runtimex.CommitPreviewResult, error) {
 846: 			return runtimex.CommitPreviewResult{Message: input.Message, FileCount: len(scope.Files)}, nil
 847: 		},
 848: 		RepairFile: func(input runtimex.RepairFileInput) (runtimex.RepairFileResult, error) {
 849: 			relativePath, err := requireAllowedRepairPath(input.Path, allowed)
 850: 			if err != nil {
 851: 				return runtimex.RepairFileResult{}, err
 852: 			}
 853: 			absolutePath, err := repoFilePath(runtime.CWD, relativePath)
 854: 			if err != nil {
 855: 				return runtimex.RepairFileResult{}, err
 856: 			}
 857: 			if err := os.WriteFile(absolutePath, []byte(input.Content), 0o644); err != nil {
 858: 				return runtimex.RepairFileResult{}, err
 859: 			}
 860: 			return runtimex.RepairFileResult{Path: relativePath, Applied: true}, nil
 861: 		},
 862: 	})
 863: }
