1024: 	if result.Status != runtimex.RunStatusCompleted {
1025: 		last := execution.lastResult()
1026: 		if last.Git.ExitCode != 0 {
1027: 			return execution, nil
1028: 		}
1029: 		return autoCommitExecution{}, fmt.Errorf("Autonomous Commit did not complete: %s", firstNonEmptyString(result.Message, result.LimitReason, string(result.Status)))
1030: 	}
1031: 	return execution, nil
1032: }
