1222: func autoCommitPlanFromCreateCommitsInput(input runtimex.CreateCommitsInput, scope gitpkg.CommitScope) (autoCommitPlan, error) {
1223: 	if len(input.Commits) == 0 {
1224: 		return autoCommitPlan{}, fmt.Errorf("create_commits requires at least one commit")
1225: 	}
1226: 	filesByPath := map[string]gitpkg.FileStatus{}
1227: 	for _, file := range scope.Files {
1228: 		filesByPath[file.Path] = file
1229: 	}
1230: 	commits := make([]autoPlannedCommit, 0, len(input.Commits))
1231: 	used := map[string]bool{}
1232: 	for _, commit := range input.Commits {
1233: 		if strings.TrimSpace(commit.Message) == "" {
1234: 			return autoCommitPlan{}, fmt.Errorf("commit message is required")
1235: 		}
1236: 		files := make([]gitpkg.FileStatus, 0, len(commit.Files))
1237: 		for _, path := range commit.Files {
1238: 			relativePath, err := normalizeRepoRelativePath(path)
1239: 			if err != nil {
1240: 				return autoCommitPlan{}, err
1241: 			}
1242: 			file, ok := filesByPath[relativePath]
1243: 			if !ok {
1244: 				return autoCommitPlan{}, fmt.Errorf("commit plan references file outside Commit Scope: %s", relativePath)
1245: 			}
1246: 			if used[relativePath] {
1247: 				return autoCommitPlan{}, fmt.Errorf("commit plan assigns file more than once: %s", relativePath)
1248: 			}
1249: 			used[relativePath] = true
1250: 			files = append(files, file)
1251: 		}
1252: 		if len(files) == 0 {
1253: 			return autoCommitPlan{}, fmt.Errorf("commit plan contains an empty commit")
1254: 		}
1255: 		commits = append(commits, autoPlannedCommit{Message: commit.Message, Files: files})
1256: 	}
1257: 	return autoCommitPlan{Kind: emptyDefaultString(input.Kind, defaultCommitPlanKind(len(commits))), Commits: commits, SplitLimitations: autoSplitLimitationsFromRuntime(input.SplitLimitations)}, nil
1258: }
