 927: func workingTreeDiffProvider(runtime Runtime, scope gitpkg.CommitScope) tui.DiffProvider {
 928: 	pathSet := map[string]bool{}
 929: 	for _, file := range scope.Files {
 930: 		pathSet[file.Path] = true
 931: 	}
 932: 	return func(path string) (string, error) {
 933: 		if !pathSet[path] {
 934: 			return "", fmt.Errorf("path is outside Commit Scope: %s", path)
 935: 		}
 936: 		isUntracked := false
 937: 		for _, file := range scope.Files {
 938: 			if file.Path == path {
 939: 				isUntracked = file.Untracked
 940: 				break
 941: 			}
 942: 		}
 943: 		if isUntracked {
 944: 			absolute, err := repoFilePath(runtime.CWD, path)
 945: 			if err != nil {
 946: 				return "", err
 947: 			}
 948: 			content, err := os.ReadFile(absolute)
 949: 			if err != nil {
 950: 				return "", err
 951: 			}
 952: 			return formatUntrackedDiff(path, string(content)), nil
 953: 		}
 954: 		args := []string{"diff", "HEAD", "--", path}
 955: 		result, err := gitpkg.DefaultCommandRunner(runtime.CWD, args, runtime.Env)
 956: 		if err != nil {
 957: 			return "", err
 958: 		}
 959: 		if result.ExitCode != 0 {
 960: 			return "", fmt.Errorf("%s", firstNonEmptyString(result.Stderr, result.Stdout, "git diff failed"))
 961: 		}
 962: 		if strings.TrimSpace(result.Stdout) == "" {
 963: 			args = []string{"diff", "--cached", "--", path}
 964: 			result, err = gitpkg.DefaultCommandRunner(runtime.CWD, args, runtime.Env)
 965: 			if err != nil {
 966: 				return "", err
 967: 			}
 968: 			if result.ExitCode != 0 {
 969: 				return "", fmt.Errorf("%s", firstNonEmptyString(result.Stderr, result.Stdout, "git diff failed"))
 970: 			}
 971: 		}
 972: 		return result.Stdout, nil
 973: 	}
 974: }
