 976: func formatUntrackedDiff(path, content string) string {
 977: 	lines := strings.Split(content, "\n")
 978: 	var b strings.Builder
 979: 	fmt.Fprintf(&b, "diff --git a/%s b/%s\n", path, path)
 980: 	b.WriteString("new file mode 100644\n")
 981: 	fmt.Fprintf(&b, "--- /dev/null\n+++ b/%s\n", path)
 982: 	fmt.Fprintf(&b, "@@ -0,0 +1,%d @@\n", len(lines))
 983: 	for _, line := range lines {
 984: 		b.WriteString("+")
 985: 		b.WriteString(line)
 986: 		b.WriteString("\n")
 987: 	}
 988: 	return b.String()
 989: }
