1181: 		RetryCount:   execution.RetryCount,
1182: 	}
1183: 	for _, commit := range execution.Results {
1184: 		summary := runtimex.CreateCommitResultSummary{
1185: 			Hash:     commit.Hash,
1186: 			Message:  commit.Message,
1187: 			ExitCode: commit.Git.ExitCode,
1188: 		}
1189: 		if commit.Git.ExitCode != 0 {
1190: 			summary.Error = firstNonEmptyString(commit.Git.Stderr, commit.Git.Stdout, "git commit failed")
1191: 			result.Status = "commit_failed"
1192: 			if result.Error == "" {
1193: 				result.Error = summary.Error
1194: 			}
1195: 		}
1196: 		result.Commits = append(result.Commits, summary)
1197: 	}
