1737: 			if err != nil {
1738: 				return parsed, err
1739: 			}
1740: 			parsed.MessageLanguage = value
1741: 			index = next
1742: 		case "--standing-instruction":
1743: 			value, next, err := requireNextArg(args, index)
1744: 			if err != nil {
