1353: 	if snapshotErr != nil {
1354: 		return autoCommitExecution{}, snapshotErr
1355: 	}
1356: 	for _, plannedCommit := range commitPlan.Commits {
1357: 		commitScope := scope
1358: 		commitScope.Files = append([]gitpkg.FileStatus{}, plannedCommit.Files...)
1359: 		commitResult, err := gitpkg.CommitScopeWithMessage(gitpkg.CommitScopeCommitOptions{
1360: 			CWD:      runtime.CWD,
1361: 			Env:      runtime.Env,
1362: 			Scope:    commitScope,
1363: 			Message:  plannedCommit.Message,
1364: 			NoVerify: parsed.NoVerify,
1365: 		})
1366: 		if err != nil {
1367: 			return autoCommitExecution{}, err
1368: 		}
1369: 		execution.Results = append(execution.Results, commitResult)
1370: 		if commitResult.Git.ExitCode != 0 {
1371: 			if len(execution.successfulResults()) > 0 {
1372: 				execution.Transaction = gitpkg.RollbackCommitTransaction(runtime.CWD, runtime.Env, snapshot, nil)
1373: 			}
1374: 			return execution, nil
1375: 		}
1376: 	}
1377: 	return execution, nil
