1508: 		if arg == "--" {
1509: 			parsed.Pathspecs = append(parsed.Pathspecs, args[index+1:]...)
1510: 			return parsed, nil
1511: 		}
1512: 		switch arg {
1513: 		case "--help", "-h":
1514: 			return parsed, errAutoHelp
1515: 		case "--dry-run":
1516: 			parsed.DryRun = true
1517: 		case "--json":
1518: 			parsed.JSON = true
1519: 		case "--tui", "-i":
1520: 			parsed.TUI = true
1521: 		case "--staged":
1522: 			parsed.Staged = true
1523: 		case "--no-untracked":
1524: 			parsed.NoUntracked = true
1525: 		case "--diff-only":
1526: 			parsed.DiffOnly = true
1527: 		case "--no-verify":
1528: 			parsed.NoVerify = true
1529: 		case "--verbose", "-v":
1530: 			parsed.Verbose = true
1531: 		case "--instruction", "-m":
1532: 			if index+1 >= len(args) {
1533: 				return parsed, fmt.Errorf("%s requires a value", arg)
1534: 			}
1535: 			parsed.Instruction = args[index+1]
1536: 			index++
1537: 		default:
1538: 			if strings.HasPrefix(arg, "--instruction=") {
1539: 				parsed.Instruction = strings.TrimPrefix(arg, "--instruction=")
1540: 				continue
1541: 			}
1542: 			if strings.HasPrefix(arg, "-m=") {
1543: 				parsed.Instruction = strings.TrimPrefix(arg, "-m=")
