679: func truncateDiff(diff string, maxBytes int) (string, DiffMetadata) {
680: 	buffer := []byte(diff)
681: 	if len(buffer) <= maxBytes {
682: 		return diff, DiffMetadata{Bytes: len(buffer), OriginalBytes: len(buffer), Truncated: false, OmittedBytes: 0, MaxBytes: maxBytes}
683: 	}
684: 	truncated := string(buffer[:maxBytes])
685: 	suffix := fmt.Sprintf("\n[cnm: diff truncated; omitted %d bytes]\n", len(buffer)-maxBytes)
686: 	result := truncated + suffix
687: 	return result, DiffMetadata{Bytes: len([]byte(result)), OriginalBytes: len(buffer), Truncated: true, OmittedBytes: len(buffer) - maxBytes, MaxBytes: maxBytes}
688: }
