396: 		gitRunner = DefaultCommandRunner
397: 	}
398: 	headResult := normalizeRunnerResult(gitRunner(cwd, []string{"rev-parse", "HEAD"}, env))
399: 	if headResult.ExitCode != 0 {
400: 		return CommitTransactionSnapshot{}, fmt.Errorf("%s", formatGitFailure("git rev-parse HEAD", headResult.Stderr, headResult.Stdout))
401: 	}
402: 	statusResult := normalizeRunnerResult(gitRunner(cwd, []string{"status", "--porcelain=v1", "-z", "--untracked-files=all"}, env))
403: 	if statusResult.ExitCode != 0 {
404: 		return CommitTransactionSnapshot{}, fmt.Errorf("%s", formatGitFailure("git status --porcelain", statusResult.Stderr, statusResult.Stdout))
405: 	}
406: 	return CommitTransactionSnapshot{Head: strings.TrimSpace(headResult.Stdout), Status: statusResult.Stdout}, nil
407: }
