430: func commitWithMessageOptions(cwd, message string, env map[string]string, gitRunner CommandRunner, noVerify bool) (CommandResult, error) {
431: 	tempDir, err := os.MkdirTemp("", "cnm-commit-")
432: 	if err != nil {
433: 		return CommandResult{ExitCode: 1, Stderr: err.Error()}, nil
434: 	}
435: 	defer os.RemoveAll(tempDir)
436: 
437: 	messagePath := filepath.Join(tempDir, "COMMIT_EDITMSG")
438: 	if err := os.WriteFile(messagePath, []byte(strings.TrimSpace(message)+"\n"), 0o600); err != nil {
439: 		return CommandResult{ExitCode: 1, Stderr: err.Error()}, nil
440: 	}
441: 
442: 	args := []string{"commit", "-F", messagePath}
443: 	if noVerify {
444: 		args = append(args, "--no-verify")
445: 	}
446: 	return normalizeRunnerResult(gitRunner(cwd, args, env)), nil
447: }
