449: func detectRepository(cwd string, env map[string]string, gitRunner CommandRunner) RepositoryState {
450: 	bareResult := normalizeRunnerResult(gitRunner(cwd, []string{"rev-parse", "--is-bare-repository"}, env))
451: 	if bareResult.ExitCode != 0 {
452: 		return RepositoryState{}
453: 	}
454: 
455: 	isBare := strings.TrimSpace(bareResult.Stdout) == "true"
456: 	rootResult := normalizeRunnerResult(gitRunner(cwd, []string{"rev-parse", "--show-toplevel"}, env))
457: 	gitDirResult := normalizeRunnerResult(gitRunner(cwd, []string{"rev-parse", "--git-dir"}, env))
458: 	headResult := normalizeRunnerResult(gitRunner(cwd, []string{"rev-parse", "--verify", "HEAD"}, env))
459: 	branchResult := normalizeRunnerResult(gitRunner(cwd, []string{"symbolic-ref", "--quiet", "--short", "HEAD"}, env))
460: 	nameResult := normalizeRunnerResult(gitRunner(cwd, []string{"config", "--get", "user.name"}, env))
461: 	emailResult := normalizeRunnerResult(gitRunner(cwd, []string{"config", "--get", "user.email"}, env))
462: 
463: 	rootPath := stringPtr(cwd)
464: 	if trimmed := strings.TrimSpace(rootResult.Stdout); rootResult.ExitCode == 0 && trimmed != "" {
465: 		rootPath = stringPtr(trimmed)
466: 	}
467: 
468: 	var gitDirPath *string
469: 	if trimmed := strings.TrimSpace(gitDirResult.Stdout); gitDirResult.ExitCode == 0 && trimmed != "" {
470: 		base := cwd
471: 		if rootPath != nil {
472: 			base = *rootPath
473: 		}
474: 		gitDirPath = stringPtr(toAbsolutePath(base, trimmed))
475: 	}
476: 
477: 	var branchName *string
478: 	if trimmed := strings.TrimSpace(branchResult.Stdout); branchResult.ExitCode == 0 && trimmed != "" {
479: 		branchName = stringPtr(trimmed)
480: 	}
481: 
482: 	var name *string
483: 	if trimmed := strings.TrimSpace(nameResult.Stdout); nameResult.ExitCode == 0 && trimmed != "" {
484: 		name = stringPtr(trimmed)
485: 	}
486: 
487: 	var email *string
488: 	if trimmed := strings.TrimSpace(emailResult.Stdout); emailResult.ExitCode == 0 && trimmed != "" {
489: 		email = stringPtr(trimmed)
490: 	}
491: 
492: 	repository := RepositoryState{
493: 		IsRepository:         true,
494: 		RootPath:             rootPath,
495: 		GitDirPath:           gitDirPath,
496: 		IsBare:               isBare,
497: 		IsInitialCommit:      headResult.ExitCode != 0,
498: 		IsDetachedHead:       headResult.ExitCode == 0 && branchResult.ExitCode != 0,
499: 		BranchName:           branchName,
500: 		MergeInProgress:      false,
501: 		RebaseInProgress:     false,
502: 		CherryPickInProgress: false,
503: 		HasGitIdentity:       name != nil && email != nil,
504: 	}
505: 	repository.GitIdentity.Name = name
506: 	repository.GitIdentity.Email = email
507: 
508: 	if gitDirPath != nil {
509: 		repository.MergeInProgress = fileExists(filepath.Join(*gitDirPath, "MERGE_HEAD"))
510: 		repository.RebaseInProgress = fileExists(filepath.Join(*gitDirPath, "rebase-merge")) || fileExists(filepath.Join(*gitDirPath, "rebase-apply"))
511: 		repository.CherryPickInProgress = fileExists(filepath.Join(*gitDirPath, "CHERRY_PICK_HEAD"))
512: 	}
513: 
514: 	return repository
515: }
