559: func parsePorcelainStatus(output string) []FileStatus {
560: 	if output == "" {
561: 		return []FileStatus{}
562: 	}
563: 	entries := splitNullSeparated(output)
564: 	files := map[string]FileStatus{}
565: 
566: 	for index := 0; index < len(entries); index++ {
567: 		entry := entries[index]
568: 		if entry == "" {
569: 			continue
570: 		}
571: 		x := byte(' ')
572: 		y := byte(' ')
573: 		if len(entry) > 0 {
574: 			x = entry[0]
575: 		}
576: 		if len(entry) > 1 {
577: 			y = entry[1]
578: 		}
579: 		rawPath := ""
580: 		if len(entry) > 3 {
581: 			rawPath = entry[3:]
582: 		}
583: 
584: 		if x == '?' && y == '?' {
585: 			mergeFileStatus(files, FileStatus{Path: rawPath, Untracked: true, Binary: false})
586: 			continue
587: 		}
588: 
589: 		if (x == 'R' || x == 'C') && index+1 < len(entries) {
590: 			originalPath := entries[index+1]
591: 			index++
592: 			mergeFileStatus(files, FileStatus{
593: 				Path:         rawPath,
594: 				OriginalPath: stringPtr(originalPath),
595: 				Staged:       changeKind(x),
596: 				Unstaged:     changeKind(y),
597: 				Binary:       false,
598: 			})
599: 			continue
600: 		}
601: 
602: 		mergeFileStatus(files, FileStatus{
603: 			Path:      rawPath,
604: 			Staged:    changeKind(x),
605: 			Unstaged:  changeKind(y),
606: 			Binary:    false,
607: 			Untracked: false,
608: 		})
609: 	}
610: 
611: 	result := make([]FileStatus, 0, len(files))
612: 	for _, file := range files {
613: 		result = append(result, file)
614: 	}
615: 	sort.Slice(result, func(i, j int) bool { return result[i].Path < result[j].Path })
616: 	return result
617: }
618: 
619: func applyBinaryMetadata(files []FileStatus, numstatOutput string) []FileStatus {
620: 	if numstatOutput == "" {
621: 		return files
622: 	}
623: 	binaryPaths := map[string]bool{}
624: 	for _, entry := range splitNullSeparated(numstatOutput) {
625: 		parts := strings.Split(entry, "\t")
626: 		if len(parts) >= 3 && parts[0] == "-" && parts[1] == "-" && parts[2] != "" {
627: 			binaryPaths[parts[2]] = true
628: 		}
629: 	}
630: 	result := make([]FileStatus, 0, len(files))
631: 	for _, file := range files {
632: 		if binaryPaths[file.Path] {
633: 			file.Binary = true
634: 		}
635: 		result = append(result, file)
636: 	}
637: 	return result
638: }
