670: func scopedGitArgs(base []string, pathspecs []string) []string {
671: 	args := append([]string{}, base...)
672: 	if len(pathspecs) > 0 {
673: 		args = append(args, "--")
674: 		args = append(args, pathspecs...)
675: 	}
676: 	return args
677: }
