690: func addBlockingIssue(inspection Inspection, issue Issue) Inspection {
691: 	inspection.Issues = append(inspection.Issues, issue)
692: 	inspection.BlockingIssues = append(inspection.BlockingIssues, issue)
693: 	return inspection
