700: func splitIssues(issues []Issue) ([]Issue, []Issue) {
701: 	warnings := make([]Issue, 0)
702: 	blocking := make([]Issue, 0)
703: 	for _, issue := range issues {
704: 		if issue.Severity == IssueSeverityBlocking {
705: 			blocking = append(blocking, issue)
706: 		} else {
707: 			warnings = append(warnings, issue)
708: 		}
709: 	}
710: 	return warnings, blocking
