713: func filterFiles(files []FileStatus, include func(FileStatus) bool) []FileStatus {
714: 	result := make([]FileStatus, 0)
715: 	for _, file := range files {
716: 		if include(file) {
717: 			result = append(result, file)
718: 		}
719: 	}
720: 	return result
