787: func normalizeRunnerResult(result CommandResult, err error) CommandResult {
788: 	if err != nil {
789: 		if result.ExitCode == 0 {
790: 			result.ExitCode = 1
791: 		}
792: 		if strings.TrimSpace(result.Stderr) == "" {
793: 			result.Stderr = err.Error()
794: 		}
795: 	}
796: 	return result
797: }
