820: func asExitError(err error, target **exec.ExitError) bool {
821: 	if err == nil {
822: 		return false
823: 	}
824: 	exitError, ok := err.(*exec.ExitError)
825: 	if !ok {
826: 		return false
827: 	}
828: 	*target = exitError
829: 	return true
830: }
