837: func toAbsolutePath(basePath, candidatePath string) string {
838: 	if filepath.IsAbs(candidatePath) {
839: 		return candidatePath
840: 	}
841: 	return filepath.Clean(filepath.Join(basePath, candidatePath))
842: }
