853: func splitNullSeparated(output string) []string {
854: 	parts := strings.Split(output, "\x00")
855: 	result := make([]string, 0, len(parts))
856: 	for _, part := range parts {
857: 		if part != "" {
858: 			result = append(result, part)
859: 		}
860: 	}
861: 	return result
862: }
