  1: package doctor
  2: 
  3: import (
  4: 	"os"
  5: 	"runtime"
  6: 	"strings"
  7: 
  8: 	"github.com/ByteTrue/commit-now-myfriend/internal/config"
  9: 	gitpkg "github.com/ByteTrue/commit-now-myfriend/internal/git"
 10: 	"github.com/ByteTrue/commit-now-myfriend/internal/providers"
 11: )
 12: 
 13: type RunOptions struct {
 14: 	CWD           string
 15: 	Env           map[string]string
 16: 	SecretStore   config.SecretStore
 17: 	ProbeProvider bool
 18: 	Probe         func(ProbeInput) ProbeResult
 19: }
 20: 
 21: const fixedProviderProbeContent = "cnm provider capability probe: fixed non-repository content."
 22: 
 23: func Run(options RunOptions) (Report, error) {
 24: 	resolvedConfig, err := config.ResolveEffectiveConfig(config.ResolveConfigOptions{CWD: options.CWD, Env: options.Env, SecretStore: options.SecretStore})
 25: 	if err != nil {
 26: 		return Report{}, err
 27: 	}
 28: 
 29: 	inspection, err := gitpkg.InspectRepository(gitpkg.InspectOptions{CWD: options.CWD, Env: options.Env})
 30: 	if err != nil {
 31: 		return Report{}, err
 32: 	}
 33: 
 34: 	report := Report{
 35: 		Command:  "cnm doctor",
 36: 		OK:       true,
 37: 		ReadOnly: true,
 38: 		Status:   "ok",
 39: 		Issues:   []Issue{},
 40: 	}
 41: 	report.Paths.ProjectConfigPath = resolvedConfig.Paths.ProjectConfigPath
 42: 	report.Paths.UserConfigHome = resolvedConfig.Paths.UserConfigHome
 43: 	report.Paths.UserConfigPath = resolvedConfig.Paths.UserConfigPath
 44: 
 45: 	gitVersion, gitAvailable := detectGitVersion(options.CWD, options.Env)
 46: 	report.Checks.Git.Available = gitAvailable
 47: 	report.Checks.Git.Version = gitVersion
 48: 	if gitAvailable {
 49: 		report.Checks.Git.Status = CheckStatusPass
 50: 		report.Checks.Git.Message = "Git is available."
 51: 	} else {
 52: 		report.Checks.Git.Status = CheckStatusError
 53: 		report.Checks.Git.Message = "Git is not available on PATH."
 54: 		report.Issues = append(report.Issues, Issue{Code: "git_unavailable", Check: "git", Message: report.Checks.Git.Message, Severity: SeverityError})
 55: 	}
 56: 
 57: 	report.Checks.Repository.IsRepository = inspection.Repository.IsRepository
 58: 	report.Checks.Repository.RootPath = inspection.Repository.RootPath
 59: 	if inspection.Repository.IsRepository {
 60: 		report.Checks.Repository.Status = CheckStatusPass
 61: 		report.Checks.Repository.Message = "Repository inspection completed."
 62: 	} else {
 63: 		report.Checks.Repository.Status = CheckStatusWarning
 64: 		report.Checks.Repository.Message = "Current directory is not inside a git repository."
 65: 		report.Issues = append(report.Issues, Issue{Code: "not_git_repository", Check: "repository", Message: report.Checks.Repository.Message, Severity: SeverityWarning})
 66: 	}
 67: 
 68: 	cfgView := config.ToJSONConfigView(resolvedConfig.Values)
 69: 	report.Checks.EffectiveConfig.Config = cfgView
 70: 	report.Checks.EffectiveConfig.Sources = ConfigSources{
 71: 		Provider: sourceLabel(resolvedConfig.UserConfig.Provider != nil, resolvedConfig.ProjectConfig.Provider != nil, resolvedConfig.EnvConfig.Provider != nil, true),
 72: 		Model:    sourceLabel(resolvedConfig.UserConfig.Model != nil, resolvedConfig.ProjectConfig.Model != nil, resolvedConfig.EnvConfig.Model != nil, true),
 73: 		BaseURL:  sourceLabel(resolvedConfig.UserConfig.BaseURL != nil, resolvedConfig.ProjectConfig.BaseURL != nil, resolvedConfig.EnvConfig.BaseURL != nil, resolvedConfig.Values.BaseURL != nil),
 74: 		APIKey:   sourceLabel(resolvedConfig.UserConfig.APIKey != nil, false, resolvedConfig.EnvConfig.APIKey != nil, resolvedConfig.Values.APIKey != nil),
 75: 	}
 76: 	configIssues := collectConfigIssues(resolvedConfig, inspection)
 77: 	report.Issues = append(report.Issues, configIssues...)
 78: 	if len(configIssues) == 0 {
 79: 		report.Checks.EffectiveConfig.Status = CheckStatusPass
 80: 		report.Checks.EffectiveConfig.Message = "Effective provider configuration looks usable."
 81: 	} else {
 82: 		report.Checks.EffectiveConfig.Status = CheckStatusError
 83: 		report.Checks.EffectiveConfig.Message = "Provider configuration needs attention."
 84: 	}
 85: 
 86: 	for _, warning := range resolvedConfig.Warnings {
 87: 		report.Issues = append(report.Issues, Issue{Code: "project_api_key_ignored", Check: "effectiveConfig", Message: warning, Severity: SeverityWarning})
 88: 	}
 89: 	if hasInsecureUserConfigPermissions(report.Paths.UserConfigPath) {
 90: 		report.Issues = append(report.Issues, Issue{Code: "user_config_permissions_insecure", Check: "effectiveConfig", Message: "User config permissions are broader than 0600.", Severity: SeverityWarning})
 91: 	}
 92: 	for _, gitIssue := range append(inspection.BlockingIssues, inspection.Warnings...) {
 93: 		severity := SeverityWarning
 94: 		if gitIssue.Severity == gitpkg.IssueSeverityBlocking && gitIssue.Code != "not_git_repository" {
 95: 			severity = SeverityError
 96: 		}
 97: 		report.Issues = append(report.Issues, Issue{Code: gitIssue.Code, Check: "repository", Message: gitIssue.Message, Severity: severity})
 98: 	}
 99: 
100: 	if capability, ok := providers.CapabilityForProvider(resolvedConfig.Values.Provider); ok {
101: 		report.Checks.ProviderCapability.Status = CheckStatusPass
102: 		report.Checks.ProviderCapability.Capability = capability
103: 		report.Checks.ProviderCapability.Message = "Provider protocol supports native Domain Tool calls."
104: 	} else {
105: 		report.Checks.ProviderCapability.Status = CheckStatusError
106: 		report.Checks.ProviderCapability.Message = "Provider protocol capability metadata is unavailable."
107: 		report.Issues = append(report.Issues, Issue{Code: "provider_capability_missing", Check: "providerCapability", Message: report.Checks.ProviderCapability.Message, Severity: SeverityError})
108: 	}
109: 
110: 	if options.ProbeProvider {
111: 		probe := options.Probe
112: 		if probe == nil {
