104: 	} else {
105: 		report.Checks.ProviderCapability.Status = CheckStatusError
106: 		report.Checks.ProviderCapability.Message = "Provider protocol capability metadata is unavailable."
107: 		report.Issues = append(report.Issues, Issue{Code: "provider_capability_missing", Check: "providerCapability", Message: report.Checks.ProviderCapability.Message, Severity: SeverityError})
108: 	}
109: 
110: 	if options.ProbeProvider {
111: 		probe := options.Probe
112: 		if probe == nil {
113: 			probe = defaultProbeProvider
114: 		}
115: 		result := probe(ProbeInput{Provider: resolvedConfig.Values.Provider, Model: resolvedConfig.Values.Model, Content: fixedProviderProbeContent})
116: 		report.Probe = &result
117: 		if result.Status != "ok" && result.Status != "skipped" {
118: 			report.Issues = append(report.Issues, Issue{Code: "provider_probe_failed", Check: "providerProbe", Message: firstNonEmpty(result.Error, result.Message, "Provider probe failed."), Severity: SeverityError})
119: 		}
120: 	}
121: 
122: 	for _, issue := range report.Issues {
123: 		if issue.Severity == SeverityError {
124: 			report.Summary.Errors++
125: 		} else if issue.Severity == SeverityWarning {
126: 			report.Summary.Warnings++
127: 		}
128: 	}
129: 	if report.Summary.Errors > 0 {
130: 		report.OK = false
131: 		report.Status = "issues_found"
132: 	}
133: 
134: 	return report, nil
135: }
