  1: package doctor
  2: 
  3: import (
  4: 	"os"
  5: 	"runtime"
  6: 	"strings"
  7: 
  8: 	"github.com/ByteTrue/commit-now-myfriend/internal/config"
  9: 	gitpkg "github.com/ByteTrue/commit-now-myfriend/internal/git"
 10: 	"github.com/ByteTrue/commit-now-myfriend/internal/providers"
 11: )
 12: 
 13: type RunOptions struct {
 14: 	CWD           string
 15: 	Env           map[string]string
 16: 	SecretStore   config.SecretStore
 17: 	ProbeProvider bool
 18: 	Probe         func(ProbeInput) ProbeResult
 19: }
 20: 
 21: const fixedProviderProbeContent = "cnm provider capability probe: fixed non-repository content."
 22: 
 23: func Run(options RunOptions) (Report, error) {
 24: 	resolvedConfig, err := config.ResolveEffectiveConfig(config.ResolveConfigOptions{CWD: options.CWD, Env: options.Env, SecretStore: options.SecretStore})
 25: 	if err != nil {
 26: 		return Report{}, err
 27: 	}
 28: 
 29: 	inspection, err := gitpkg.InspectRepository(gitpkg.InspectOptions{CWD: options.CWD, Env: options.Env})
 30: 	if err != nil {
 31: 		return Report{}, err
 32: 	}
 33: 
 34: 	report := Report{
 35: 		Command:  "cnm doctor",
 36: 		OK:       true,
 37: 		ReadOnly: true,
 38: 		Status:   "ok",
 39: 		Issues:   []Issue{},
 40: 	}
 41: 	report.Paths.ProjectConfigPath = resolvedConfig.Paths.ProjectConfigPath
 42: 	report.Paths.UserConfigHome = resolvedConfig.Paths.UserConfigHome
 43: 	report.Paths.UserConfigPath = resolvedConfig.Paths.UserConfigPath
 44: 
 45: 	gitVersion, gitAvailable := detectGitVersion(options.CWD, options.Env)
 46: 	report.Checks.Git.Available = gitAvailable
 47: 	report.Checks.Git.Version = gitVersion
 48: 	if gitAvailable {
 49: 		report.Checks.Git.Status = CheckStatusPass
 50: 		report.Checks.Git.Message = "Git is available."
 51: 	} else {
 52: 		report.Checks.Git.Status = CheckStatusError
 53: 		report.Checks.Git.Message = "Git is not available on PATH."
 54: 		report.Issues = append(report.Issues, Issue{Code: "git_unavailable", Check: "git", Message: report.Checks.Git.Message, Severity: SeverityError})
 55: 	}
 56: 
 57: 	report.Checks.Repository.IsRepository = inspection.Repository.IsRepository
 58: 	report.Checks.Repository.RootPath = inspection.Repository.RootPath
 59: 	if inspection.Repository.IsRepository {
 60: 		report.Checks.Repository.Status = CheckStatusPass
 61: 		report.Checks.Repository.Message = "Repository inspection completed."
 62: 	} else {
 63: 		report.Checks.Repository.Status = CheckStatusWarning
 64: 		report.Checks.Repository.Message = "Current directory is not inside a git repository."
 65: 		report.Issues = append(report.Issues, Issue{Code: "not_git_repository", Check: "repository", Message: report.Checks.Repository.Message, Severity: SeverityWarning})
 66: 	}
 67: 
 68: 	cfgView := config.ToJSONConfigView(resolvedConfig.Values)
 69: 	report.Checks.EffectiveConfig.Config = cfgView
 70: 	report.Checks.EffectiveConfig.Sources = ConfigSources{
 71: 		Provider: sourceLabel(resolvedConfig.UserConfig.Provider != nil, resolvedConfig.ProjectConfig.Provider != nil, resolvedConfig.EnvConfig.Provider != nil, true),
 72: 		Model:    sourceLabel(resolvedConfig.UserConfig.Model != nil, resolvedConfig.ProjectConfig.Model != nil, resolvedConfig.EnvConfig.Model != nil, true),
 73: 		BaseURL:  sourceLabel(resolvedConfig.UserConfig.BaseURL != nil, resolvedConfig.ProjectConfig.BaseURL != nil, resolvedConfig.EnvConfig.BaseURL != nil, resolvedConfig.Values.BaseURL != nil),
 74: 		APIKey:   sourceLabel(resolvedConfig.UserConfig.APIKey != nil, false, resolvedConfig.EnvConfig.APIKey != nil, resolvedConfig.Values.APIKey != nil),
 75: 	}
 76: 	configIssues := collectConfigIssues(resolvedConfig, inspection)
 77: 	report.Issues = append(report.Issues, configIssues...)
 78: 	if len(configIssues) == 0 {
 79: 		report.Checks.EffectiveConfig.Status = CheckStatusPass
 80: 		report.Checks.EffectiveConfig.Message = "Effective provider configuration looks usable."
 81: 	} else {
 82: 		report.Checks.EffectiveConfig.Status = CheckStatusError
 83: 		report.Checks.EffectiveConfig.Message = "Provider configuration needs attention."
 84: 	}
 85: 
 86: 	for _, warning := range resolvedConfig.Warnings {
 87: 		report.Issues = append(report.Issues, Issue{Code: "project_api_key_ignored", Check: "effectiveConfig", Message: warning, Severity: SeverityWarning})
 88: 	}
 89: 	if hasInsecureUserConfigPermissions(report.Paths.UserConfigPath) {
 90: 		report.Issues = append(report.Issues, Issue{Code: "user_config_permissions_insecure", Check: "effectiveConfig", Message: "User config permissions are broader than 0600.", Severity: SeverityWarning})
 91: 	}
 92: 	for _, gitIssue := range append(inspection.BlockingIssues, inspection.Warnings...) {
 93: 		severity := SeverityWarning
 94: 		if gitIssue.Severity == gitpkg.IssueSeverityBlocking && gitIssue.Code != "not_git_repository" {
 95: 			severity = SeverityError
 96: 		}
 97: 		report.Issues = append(report.Issues, Issue{Code: gitIssue.Code, Check: "repository", Message: gitIssue.Message, Severity: severity})
 98: 	}
 99: 
100: 	if capability, ok := providers.CapabilityForProvider(resolvedConfig.Values.Provider); ok {
101: 		report.Checks.ProviderCapability.Status = CheckStatusPass
102: 		report.Checks.ProviderCapability.Capability = capability
103: 		report.Checks.ProviderCapability.Message = "Provider protocol supports native Domain Tool calls."
104: 	} else {
105: 		report.Checks.ProviderCapability.Status = CheckStatusError
106: 		report.Checks.ProviderCapability.Message = "Provider protocol capability metadata is unavailable."
107: 		report.Issues = append(report.Issues, Issue{Code: "provider_capability_missing", Check: "providerCapability", Message: report.Checks.ProviderCapability.Message, Severity: SeverityError})
108: 	}
109: 
110: 	if options.ProbeProvider {
111: 		probe := options.Probe
112: 		if probe == nil {
113: 			probe = defaultProbeProvider
114: 		}
115: 		result := probe(ProbeInput{Provider: resolvedConfig.Values.Provider, Model: resolvedConfig.Values.Model, Content: fixedProviderProbeContent})
116: 		report.Probe = &result
117: 		if result.Status != "ok" && result.Status != "skipped" {
118: 			report.Issues = append(report.Issues, Issue{Code: "provider_probe_failed", Check: "providerProbe", Message: firstNonEmpty(result.Error, result.Message, "Provider probe failed."), Severity: SeverityError})
119: 		}
120: 	}
121: 
122: 	for _, issue := range report.Issues {
123: 		if issue.Severity == SeverityError {
124: 			report.Summary.Errors++
125: 		} else if issue.Severity == SeverityWarning {
126: 			report.Summary.Warnings++
127: 		}
128: 	}
129: 	if report.Summary.Errors > 0 {
130: 		report.OK = false
131: 		report.Status = "issues_found"
132: 	}
133: 
134: 	return report, nil
135: }
136: 
137: func defaultProbeProvider(input ProbeInput) ProbeResult {
138: 	return ProbeResult{Status: "skipped", Message: "Provider probe transport is not configured in this build."}
139: }
140: 
141: func firstNonEmpty(values ...string) string {
142: 	for _, value := range values {
143: 		if strings.TrimSpace(value) != "" {
144: 			return strings.TrimSpace(value)
145: 		}
146: 	}
147: 	return ""
148: }
149: 
150: func detectGitVersion(cwd string, env map[string]string) (*string, bool) {
151: 	result, err := gitpkg.DefaultCommandRunner(cwd, []string{"--version"}, env)
152: 	if err != nil || result.ExitCode != 0 {
153: 		return nil, false
154: 	}
155: 	version := strings.TrimSpace(result.Stdout)
156: 	if version == "" {
157: 		return nil, false
158: 	}
159: 	return &version, true
160: }
161: 
162: func collectConfigIssues(resolved config.ResolvedConfig, inspection gitpkg.Inspection) []Issue {
163: 	issues := make([]Issue, 0)
164: 	defaultProviderOnly := resolved.UserConfig.Provider == nil && resolved.ProjectConfig.Provider == nil && resolved.EnvConfig.Provider == nil
165: 	defaultModelOnly := resolved.UserConfig.Model == nil && resolved.ProjectConfig.Model == nil && resolved.EnvConfig.Model == nil
166: 	if defaultProviderOnly && defaultModelOnly {
167: 		issues = append(issues, Issue{Code: "provider_config_missing", Check: "effectiveConfig", Message: "Provider configuration is still using built-in defaults; run `cnm init` or configure cnm before generating commits.", Severity: SeverityError})
168: 	}
169: 	if resolved.Values.APIKey == nil || strings.TrimSpace(*resolved.Values.APIKey) == "" {
170: 		issues = append(issues, Issue{Code: "api_key_missing", Check: "effectiveConfig", Message: "No API key is configured for " + string(resolved.Values.Provider) + ".", Severity: SeverityError})
171: 	}
172: 	if resolved.Values.Provider == config.ProviderOpenAICompatible && (resolved.Values.BaseURL == nil || strings.TrimSpace(*resolved.Values.BaseURL) == "") {
173: 		issues = append(issues, Issue{Code: "provider_config_missing", Check: "effectiveConfig", Message: "The openai-compatible provider requires `baseURL` to be configured.", Severity: SeverityError})
174: 	}
175: 	if !inspection.Repository.HasGitIdentity && inspection.Repository.IsRepository {
176: 		issues = append(issues, Issue{Code: "git_identity_missing", Check: "repository", Message: "Git user.name and user.email must be configured before committing.", Severity: SeverityError})
177: 	}
178: 	return issues
179: }
180: 
181: func sourceLabel(user bool, project bool, env bool, hasDefault bool) string {
182: 	if env {
183: 		return "env"
184: 	}
185: 	if project {
186: 		return "project"
187: 	}
188: 	if user {
189: 		return "user"
190: 	}
191: 	if hasDefault {
192: 		return "default"
193: 	}
194: 	return "missing"
195: }
196: 
197: func hasInsecureUserConfigPermissions(path string) bool {
198: 	if runtime.GOOS == "windows" || strings.TrimSpace(path) == "" {
199: 		return false
200: 	}
201: 	info, err := os.Stat(path)
202: 	if err != nil {
203: 		return false
204: 	}
205: 	return info.Mode().Perm()&0o077 != 0
206: }

text:
  1: package commands
  2: 
  3: import (
  4: 	"flag"
  5: 	"fmt"
  6: 	"io"
  7: 
  8: 	"github.com/ByteTrue/commit-now-myfriend/internal/config"
  9: 	"github.com/ByteTrue/commit-now-myfriend/internal/output"
 10: )
 11: 
 12: const plaintextAPIKeyWarning = "Warning: API keys are stored in plaintext in the user config file. Prefer environment variables when possible."
 13: 
 14: type ConfigRuntime struct {
 15: 	CWD         string
 16: 	Env         map[string]string
 17: 	Stdout      io.Writer
 18: 	Stderr      io.Writer
 19: 	SecretStore config.SecretStore
 20: }
 21: 
 22: func RunConfig(args []string, runtime ConfigRuntime) int {
 23: 	if len(args) == 0 {
 24: 		return runConfigList(nil, runtime)
 25: 	}
 26: 
 27: 	switch args[0] {
 28: 	case "get":
 29: 		return runConfigGet(args[1:], runtime)
 30: 	case "list":
 31: 		return runConfigList(args[1:], runtime)
 32: 	case "set":
 33: 		return runConfigSet(args[1:], runtime)
 34: 	case "unset":
 35: 		return runConfigUnset(args[1:], runtime)
 36: 	default:
 37: 		fmt.Fprintf(runtime.Stderr, "error: unknown config subcommand %q\n", args[0])
 38: 		return int(output.Error)
 39: 	}
 40: }
 41: 
 42: func runConfigGet(args []string, runtime ConfigRuntime) int {
 43: 	fs := flag.NewFlagSet("cnm config get", flag.ContinueOnError)
 44: 	fs.SetOutput(runtime.Stderr)
 45: 	jsonMode := fs.Bool("json", false, "emit JSON output")
 46: 	if err := fs.Parse(args); err != nil {
 47: 		return int(output.UsageError)
 48: 	}
 49: 
 50: 	router := output.NewRouter(*jsonMode, runtime.Stdout, runtime.Stderr)
 51: 	resolved, err := config.ResolveEffectiveConfig(config.ResolveConfigOptions{CWD: runtime.CWD, Env: runtime.Env, SecretStore: runtime.SecretStore})
 52: 	if err != nil {
 53: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
 54: 		return int(output.Error)
 55: 	}
 56: 	for _, warning := range resolved.Warnings {
 57: 		_ = router.WriteHuman("Warning: "+warning, output.StderrTarget)
 58: 	}
 59: 
 60: 	var key string
 61: 	if fs.NArg() > 0 {
 62: 		key = fs.Arg(0)
 63: 	}
 64: 	if fs.NArg() > 1 {
 65: 		fmt.Fprintf(runtime.Stderr, "error: unexpected config arguments: %v\n", fs.Args()[1:])
 66: 		return int(output.UsageError)
 67: 	}
 68: 
 69: 	if key != "" {
 70: 		configKey, err := config.AssertConfigKey(key)
 71: 		if err != nil {
 72: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
 73: 			return int(output.Error)
 74: 		}
 75: 		value := config.GetConfigValue(resolved.Values, configKey)
 76: 		if router.IsJSON() {
 77: 			_ = router.WriteJSON(map[string]*string{string(configKey): value})
 78: 		} else if value == nil {
 79: 			_ = router.WriteHuman(string(configKey)+"=(unset)", output.StdoutTarget)
 80: 		} else {
 81: 			_ = router.WriteHuman(string(configKey)+"="+*value, output.StdoutTarget)
 82: 		}
 83: 		return int(output.Success)
 84: 	}
 85: 
 86: 	if router.IsJSON() {
 87: 		_ = router.WriteJSON(config.ToJSONConfigView(resolved.Values))
 88: 	} else {
 89: 		for _, line := range config.ToHumanConfigLines(resolved.Values) {
 90: 			_ = router.WriteHuman(line, output.StdoutTarget)
 91: 		}
 92: 	}
 93: 	return int(output.Success)
 94: }
 95: 
 96: func runConfigList(args []string, runtime ConfigRuntime) int {
 97: 	fs := flag.NewFlagSet("cnm config list", flag.ContinueOnError)
 98: 	fs.SetOutput(runtime.Stderr)
 99: 	jsonMode := fs.Bool("json", false, "emit JSON output")
100: 	if err := fs.Parse(args); err != nil {
101: 		return int(output.UsageError)
102: 	}
103: 	if fs.NArg() > 0 {
104: 		fmt.Fprintf(runtime.Stderr, "error: unexpected config arguments: %v\n", fs.Args())
105: 		return int(output.UsageError)
106: 	}
107: 	if *jsonMode {
108: 		return runConfigGet([]string{"--json"}, runtime)
109: 	}
110: 	return runConfigGet(nil, runtime)
111: }
112: 
113: func runConfigSet(args []string, runtime ConfigRuntime) int {
114: 	fs := flag.NewFlagSet("cnm config set", flag.ContinueOnError)
115: 	fs.SetOutput(runtime.Stderr)
116: 	jsonMode := fs.Bool("json", false, "emit JSON output")
117: 	dryRun := fs.Bool("dry-run", false, "preview command execution without side effects")
118: 	if err := fs.Parse(args); err != nil {
119: 		return int(output.UsageError)
120: 	}
121: 	if fs.NArg() != 2 {
122: 		fmt.Fprintln(runtime.Stderr, "error: cnm config set requires <key> <value>")
123: 		return int(output.UsageError)
124: 	}
125: 
126: 	key := fs.Arg(0)
127: 	value := fs.Arg(1)
128: 	router := output.NewRouter(*jsonMode, runtime.Stdout, runtime.Stderr)
129: 	configKey, err := config.AssertConfigKey(key)
130: 	if err != nil {
131: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
132: 		return int(output.Error)
133: 	}
134: 	if configKey == config.ConfigKeyAPIKey {
135: 		_ = router.WriteHuman(plaintextAPIKeyWarning, output.StderrTarget)
136: 	}
137: 	masked := value
138: 	if configKey == config.ConfigKeyAPIKey {
139: 		masked = "[redacted]"
140: 	}
141: 	paths := config.GetConfigPaths(config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
142: 	if *dryRun {
143: 		payload := map[string]any{
144: 			"command": "cnm config set",
145: 			"dryRun":  true,
146: 			"key":     string(configKey),
147: 			"ok":      true,
148: 			"path":    paths.UserConfigPath,
149: 			"status":  "dry_run",
150: 			"value":   masked,
151: 		}
152: 		_ = router.WriteStructured(payload, "Dry-run: would update "+string(configKey)+" in user config at "+paths.UserConfigPath+".", output.StdoutTarget)
153: 		return int(output.Success)
154: 	}
155: 
156: 	patch, err := config.ParseKeyValue(key, value)
157: 	if err != nil {
158: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
159: 		return int(output.Error)
160: 	}
161: 	result, err := config.WriteUserConfigPatch(patch, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
162: 	if err != nil {
163: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
164: 		return int(output.Error)
165: 	}
166: 	for _, warning := range result.Warnings {
167: 		_ = router.WriteHuman("Warning: "+warning, output.StderrTarget)
168: 	}
169: 	payload := map[string]any{
170: 		"command": "cnm config set",
171: 		"dryRun":  false,
172: 		"key":     string(configKey),
173: 		"ok":      true,
174: 		"path":    result.Path,
175: 		"status":  "updated",
176: 		"value":   masked,
177: 	}
178: 	_ = router.WriteStructured(payload, "Updated user config at "+result.Path+".\n"+string(configKey)+"="+masked, output.StdoutTarget)
179: 	return int(output.Success)
180: }
181: 
182: func runConfigUnset(args []string, runtime ConfigRuntime) int {
183: 	fs := flag.NewFlagSet("cnm config unset", flag.ContinueOnError)
184: 	fs.SetOutput(runtime.Stderr)
185: 	jsonMode := fs.Bool("json", false, "emit JSON output")
186: 	dryRun := fs.Bool("dry-run", false, "preview command execution without side effects")
187: 	if err := fs.Parse(args); err != nil {
188: 		return int(output.UsageError)
189: 	}
190: 	if fs.NArg() != 1 {
191: 		fmt.Fprintln(runtime.Stderr, "error: cnm config unset requires <key>")
192: 		return int(output.UsageError)
193: 	}
194: 
195: 	key := fs.Arg(0)
196: 	configKey, err := config.AssertConfigKey(key)
197: 	if err != nil {
198: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
199: 		return int(output.Error)
200: 	}
201: 	router := output.NewRouter(*jsonMode, runtime.Stdout, runtime.Stderr)
202: 	paths := config.GetConfigPaths(config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
203: 	if *dryRun {
204: 		payload := map[string]any{
205: 			"command": "cnm config unset",
206: 			"dryRun":  true,
207: 			"key":     string(configKey),
208: 			"ok":      true,
209: 			"path":    paths.UserConfigPath,
210: 			"status":  "dry_run",
211: 		}
212: 		_ = router.WriteStructured(payload, "Dry-run: would remove "+string(configKey)+" from user config at "+paths.UserConfigPath+".", output.StdoutTarget)
213: 		return int(output.Success)
214: 	}
215: 
216: 	result, err := config.UnsetUserConfigKey(configKey, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
217: 	if err != nil {
218: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
219: 		return int(output.Error)
220: 	}
221: 	for _, warning := range result.Warnings {
222: 		_ = router.WriteHuman("Warning: "+warning, output.StderrTarget)
223: 	}
224: 	payload := map[string]any{
225: 		"command": "cnm config unset",
226: 		"dryRun":  false,
227: 		"key":     string(configKey),
228: 		"ok":      true,
229: 		"path":    result.Path,
230: 		"status":  "removed",
231: 	}
232: 	_ = router.WriteStructured(payload, "Removed "+string(configKey)+" from user config at "+result.Path+".", output.StdoutTarget)
233: 	return int(output.Success)
234: }

