152: 		_ = router.WriteStructured(payload, "Dry-run: would update "+string(configKey)+" in user config at "+paths.UserConfigPath+".", output.StdoutTarget)
153: 		return int(output.Success)
154: 	}
155: 
156: 	patch, err := config.ParseKeyValue(key, value)
157: 	if err != nil {
158: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
159: 		return int(output.Error)
160: 	}
161: 	result, err := config.WriteUserConfigPatch(patch, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
162: 	if err != nil {
163: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
164: 		return int(output.Error)
165: 	}
166: 	for _, warning := range result.Warnings {
167: 		_ = router.WriteHuman("Warning: "+warning, output.StderrTarget)
168: 	}
169: 	payload := map[string]any{
170: 		"command": "cnm config set",
171: 		"dryRun":  false,
172: 		"key":     string(configKey),
173: 		"ok":      true,
174: 		"path":    result.Path,
175: 		"status":  "updated",
176: 		"value":   masked,
177: 	}
178: 	_ = router.WriteStructured(payload, "Updated user config at "+result.Path+".\n"+string(configKey)+"="+masked, output.StdoutTarget)
179: 	return int(output.Success)
180: }
