182: func runConfigUnset(args []string, runtime ConfigRuntime) int {
183: 	fs := flag.NewFlagSet("cnm config unset", flag.ContinueOnError)
184: 	fs.SetOutput(runtime.Stderr)
185: 	jsonMode := fs.Bool("json", false, "emit JSON output")
186: 	dryRun := fs.Bool("dry-run", false, "preview command execution without side effects")
187: 	if err := fs.Parse(args); err != nil {
188: 		return int(output.UsageError)
189: 	}
190: 	if fs.NArg() != 1 {
191: 		fmt.Fprintln(runtime.Stderr, "error: cnm config unset requires <key>")
192: 		return int(output.UsageError)
193: 	}
194: 
195: 	key := fs.Arg(0)
196: 	configKey, err := config.AssertConfigKey(key)
197: 	if err != nil {
198: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
199: 		return int(output.Error)
200: 	}
201: 	router := output.NewRouter(*jsonMode, runtime.Stdout, runtime.Stderr)
202: 	paths := config.GetConfigPaths(config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
203: 	if *dryRun {
204: 		payload := map[string]any{
205: 			"command": "cnm config unset",
206: 			"dryRun":  true,
207: 			"key":     string(configKey),
208: 			"ok":      true,
209: 			"path":    paths.UserConfigPath,
210: 			"status":  "dry_run",
211: 		}
212: 		_ = router.WriteStructured(payload, "Dry-run: would remove "+string(configKey)+" from user config at "+paths.UserConfigPath+".", output.StdoutTarget)
213: 		return int(output.Success)
214: 	}
215: 
216: 	result, err := config.UnsetUserConfigKey(configKey, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
217: 	if err != nil {
218: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
219: 		return int(output.Error)
220: 	}
221: 	for _, warning := range result.Warnings {
222: 		_ = router.WriteHuman("Warning: "+warning, output.StderrTarget)
223: 	}
224: 	payload := map[string]any{
225: 		"command": "cnm config unset",
226: 		"dryRun":  false,
227: 		"key":     string(configKey),
228: 		"ok":      true,
229: 		"path":    result.Path,
230: 		"status":  "removed",
231: 	}
232: 	_ = router.WriteStructured(payload, "Removed "+string(configKey)+" from user config at "+result.Path+".", output.StdoutTarget)
233: 	return int(output.Success)
234: }

