348: func runInteractiveInit(runtime InitRuntime) int {
349: 	current, err := config.ResolveEffectiveConfig(config.ResolveConfigOptions{CWD: runtime.CWD, Env: runtime.Env, SecretStore: runtime.SecretStore})
350: 	if err != nil {
351: 		current.Values.Provider = config.DefaultProvider
352: 		current.Values.Model = config.GetDefaultModel(config.DefaultProvider)
353: 		current.Values.PromptStyle = config.DefaultPromptStyle
354: 		current.Values.MessageLanguage = config.DefaultMessageLanguage
355: 	}
356: 	if runtime.OnboardingRunner != nil {
357: 		return runOnboardingTUI(runtime, current.Values)
358: 	}
359: 	prompter := interactive.NewPrompter(runtime.Stdin, runtime.Stdout)
360: 	if _, err := fmt.Fprintln(runtime.Stdout, "Onboarding"); err != nil {
361: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
362: 		return int(output.Error)
363: 	}
364: 	provider, err := askInitProvider(prompter, current.Values.Provider)
365: 	if err != nil {
366: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
367: 		return int(output.Error)
368: 	}
369: 	model, err := askInitText(prompter, "Model", firstNonEmptyString(current.Values.Model, config.GetDefaultModel(provider)), true)
370: 	if err != nil {
371: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
372: 		return int(output.Error)
373: 	}
374: 	var baseURL *string
375: 	if provider == config.ProviderOpenAICompatible {
376: 		value, err := askInitText(prompter, "Base URL", stringPointerValue(current.Values.BaseURL), true)
377: 		if err != nil {
378: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
379: 			return int(output.Error)
380: 		}
381: 		baseURL = &value
382: 	} else {
383: 		baseURL = current.Values.BaseURL
384: 	}
385: 	promptStyle, err := askInitPromptStyle(prompter, current.Values.PromptStyle)
386: 	if err != nil {
387: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
388: 		return int(output.Error)
389: 	}
390: 	messageLanguage, err := askInitMessageLanguage(prompter, current.Values.MessageLanguage)
391: 	if err != nil {
392: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
393: 		return int(output.Error)
394: 	}
395: 	standingInstruction, err := askInitText(prompter, "Standing Instruction", stringPointerValue(current.Values.StandingInstruction), false)
396: 	if err != nil {
397: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
398: 		return int(output.Error)
399: 	}
400: 	apiKey, err := askInitText(prompter, "API key", "", true)
401: 	if err != nil {
402: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
403: 		return int(output.Error)
404: 	}
405: 
406: 	save, err := config.SaveAPIKeyToSecretStore(provider, apiKey, runtime.SecretStore)
407: 	if err != nil {
408: 		fmt.Fprintf(runtime.Stderr, "error: %v Use --plaintext-api-key to store this key in user config instead.\n", err)
409: 		return int(output.Error)
410: 	}
411: 	if !save.Stored {
412: 		message := "Secret Store is not available; use --plaintext-api-key to store this key in user config."
413: 		if save.Warning != nil {
414: 			message = *save.Warning
415: 		}
416: 		fmt.Fprintf(runtime.Stderr, "error: %s\n", message)
417: 		return int(output.Error)
418: 	}
419: 
420: 	patch := config.ConfigValues{
421: 		Provider:            &provider,
422: 		Model:               &model,
423: 		BaseURL:             baseURL,
424: 		PromptStyle:         &promptStyle,
425: 		MessageLanguage:     &messageLanguage,
426: 		StandingInstruction: optionalStringPointer(standingInstruction),
427: 	}
428: 	result, err := config.WriteUserConfigPatch(patch, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
429: 	if err != nil {
430: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
431: 		return int(output.Error)
432: 	}
433: 	for _, warning := range result.Warnings {
434: 		fmt.Fprintln(runtime.Stderr, "Warning: "+warning)
435: 	}
436: 	fmt.Fprintf(runtime.Stdout, "Initialized user config at %s.\n", result.Path)
437: 	fmt.Fprintf(runtime.Stdout, "Stored API key in Secret Store for %s.\n", save.Provider)
438: 	effective := config.EffectiveConfig{Provider: provider, Model: model, BaseURL: baseURL, PromptStyle: promptStyle, MessageLanguage: messageLanguage, APIKey: &apiKey, APIKeySource: config.APIKeySourceSecretStore, StandingInstruction: optionalStringPointer(standingInstruction)}
439: 	for _, line := range config.ToHumanConfigLines(effective) {
440: 		fmt.Fprintln(runtime.Stdout, line)
441: 	}
442: 	return int(output.Success)
443: }
444: 
445: func askInitProvider(prompter *interactive.Prompter, current config.ProviderType) (config.ProviderType, error) {
446: 	choice, err := prompter.AskChoice("Provider (openai-responses, openai-compatible, anthropic-messages, google-gemini)", providerChoiceStrings())
447: 	if err != nil {
448: 		return "", err
449: 	}
450: 	return config.ProviderType(firstNonEmptyString(choice, string(current))), nil
451: }
452: 
453: func askInitPromptStyle(prompter *interactive.Prompter, current config.PromptStyle) (config.PromptStyle, error) {
454: 	choice, err := prompter.AskChoice("Prompt style (auto, conventional, angular, google, atom, plain, custom)", promptStyleChoiceStrings())
455: 	if err != nil {
456: 		return "", err
457: 	}
458: 	return config.PromptStyle(firstNonEmptyString(choice, string(current))), nil
459: }
460: 
461: func askInitMessageLanguage(prompter *interactive.Prompter, current config.MessageLanguage) (config.MessageLanguage, error) {
462: 	choice, err := prompter.AskChoice("Message language (auto, en, zh-CN, zh-TW)", messageLanguageChoiceStrings())
463: 	if err != nil {
464: 		return "", err
465: 	}
466: 	return config.MessageLanguage(firstNonEmptyString(choice, string(current))), nil
467: }
468: 
469: func askInitText(prompter *interactive.Prompter, label string, defaultValue string, required bool) (string, error) {
470: 	for {
471: 		value, err := prompter.AskText(label, defaultValue)
472: 		if err != nil {
473: 			return "", err
474: 		}
475: 		trimmed := strings.TrimSpace(value)
476: 		if trimmed != "" || !required {
477: 			return trimmed, nil
478: 		}
479: 	}
480: }
481: 
482: func providerChoiceStrings() []string {
483: 	values := make([]string, 0, len(config.ProviderTypes))
484: 	for _, value := range config.ProviderTypes {
485: 		values = append(values, string(value))
486: 	}
487: 	return values
488: }
489: 
490: func promptStyleChoiceStrings() []string {
491: 	values := make([]string, 0, len(config.PromptStyles))
492: 	for _, value := range config.PromptStyles {
493: 		values = append(values, string(value))
494: 	}
495: 	return values
496: }
497: 
498: func messageLanguageChoiceStrings() []string {
499: 	values := make([]string, 0, len(config.MessageLanguages))
500: 	for _, value := range config.MessageLanguages {
501: 		values = append(values, string(value))
502: 	}
503: 	return values
504: }
505: 
506: func firstNonEmptyString(values ...string) string {
507: 	for _, value := range values {
508: 		if strings.TrimSpace(value) != "" {
509: 			return strings.TrimSpace(value)
510: 		}
511: 	}
512: 	return ""
513: }
514: 
515: func stringPointerValue(value *string) string {
516: 	if value == nil {
517: 		return ""
518: 	}
519: 	return *value
520: }
521: 
522: func optionalStringPointer(value string) *string {
523: 	trimmed := strings.TrimSpace(value)
524: 	if trimmed == "" {
525: 		return nil
526: 	}
527: 	return &trimmed
528: }
529: 
530: func mergeConfigValues(base config.ConfigValues, patch config.ConfigValues) config.ConfigValues {
531: 	result := base
532: 	if patch.Provider != nil {
533: 		result.Provider = patch.Provider
534: 	}
535: 	if patch.Model != nil {
536: 		result.Model = patch.Model
537: 	}
538: 	if patch.BaseURL != nil {
539: 		result.BaseURL = patch.BaseURL
540: 	}
541: 	if patch.PromptStyle != nil {
542: 		result.PromptStyle = patch.PromptStyle
543: 	}
544: 	if patch.MessageLanguage != nil {
545: 		result.MessageLanguage = patch.MessageLanguage
546: 	}
547: 	if patch.StandingInstruction != nil {
548: 		result.StandingInstruction = patch.StandingInstruction
549: 	}
550: 	if patch.APIKey != nil {
551: 		result.APIKey = patch.APIKey
552: 	}
553: 	return result
554: }

content.text:
  1: package commands
  2: 
  3: import (
  4: 	"flag"
  5: 	"fmt"
  6: 	"io"
  7: 	"strings"
  8: 
  9: 	"github.com/ByteTrue/commit-now-myfriend/internal/config"
 10: 	"github.com/ByteTrue/commit-now-myfriend/internal/interactive"
 11: 	"github.com/ByteTrue/commit-now-myfriend/internal/output"
 12: )
 13: 
 14: type InitRuntime struct {
 15: 	CWD              string
 16: 	Env              map[string]string
 17: 	Stdin            io.Reader
 18: 	Stdout           io.Writer
 19: 	Stderr           io.Writer
 20: 	IsTTY            bool
 21: 	SecretStore      config.WritableSecretStore
 22: 	OnboardingRunner OnboardingRunnerFunc
 23: }
 24: 
 25: type OnboardingAnswers struct {
 26: 	Provider            config.ProviderType
 27: 	Model               string
 28: 	BaseURL             string
 29: 	PromptStyle         config.PromptStyle
 30: 	MessageLanguage     config.MessageLanguage
 31: 	StandingInstruction string
 32: 	APIKey              string
 33: 	Cancelled           bool
 34: }
 35: 
 36: type OnboardingRunnerFunc func(OnboardingPrefill) (OnboardingAnswers, error)
 37: 
 38: type OnboardingPrefill struct {
 39: 	Provider            config.ProviderType
 40: 	Model               string
 41: 	BaseURL             string
 42: 	PromptStyle         config.PromptStyle
 43: 	MessageLanguage     config.MessageLanguage
 44: 	StandingInstruction string
 45: }
 46: 
 47: func RunInit(args []string, runtime InitRuntime) int {
 48: 	fs := flag.NewFlagSet("cnm init", flag.ContinueOnError)
 49: 	fs.SetOutput(runtime.Stderr)
 50: 	jsonMode := fs.Bool("json", false, "emit JSON output")
 51: 	dryRun := fs.Bool("dry-run", false, "preview command execution without side effects")
 52: 	providerFlag := fs.String("provider", "", "default AI provider")
 53: 	modelFlag := fs.String("model", "", "default AI model")
 54: 	baseURLFlag := fs.String("base-url", "", "OpenAI-compatible base URL")
 55: 	promptStyleFlag := fs.String("prompt-style", "", "commit prompt style")
 56: 	messageLanguageFlag := fs.String("message-language", "", "commit message language")
 57: 	standingInstructionFlag := fs.String("standing-instruction", "", "standing AI instruction")
 58: 	apiKeyFlag := fs.String("api-key", "", "API key stored in the Secret Store by default")
 59: 	plaintextAPIKeyFlag := fs.Bool("plaintext-api-key", false, "store --api-key in plaintext user config instead of the Secret Store")
 60: 	if err := fs.Parse(args); err != nil {
 61: 		return int(output.UsageError)
 62: 	}
 63: 	if fs.NArg() > 0 {
 64: 		fmt.Fprintf(runtime.Stderr, "error: unexpected init arguments: %v\n", fs.Args())
 65: 		return int(output.UsageError)
 66: 	}
 67: 	apiKeyInput := strings.TrimSpace(*apiKeyFlag)
 68: 	if *plaintextAPIKeyFlag && apiKeyInput == "" {
 69: 		fmt.Fprintln(runtime.Stderr, "error: --plaintext-api-key requires --api-key.")
 70: 		return int(output.UsageError)
 71: 	}
 72: 	hasExplicitConfig := initHasExplicitConfigFlags(fs)
 73: 	interactiveMode := runtime.IsTTY && !*jsonMode && !*dryRun && !hasExplicitConfig
 74: 	if interactiveMode {
 75: 		return runInteractiveInit(runtime)
 76: 	}
 77: 	if !runtime.IsTTY && !*jsonMode && !*dryRun && !hasExplicitConfig {
 78: 		fmt.Fprintln(runtime.Stderr, "error: cnm init requires interactive TTY input or explicit flags in non-interactive environments.")
 79: 		return int(output.UsageError)
 80: 	}
 81: 
 82: 	patch := config.ConfigValues{}
 83: 	if value := strings.TrimSpace(*providerFlag); value != "" {
 84: 		provider := config.ProviderType(value)
 85: 		if !config.IsProviderType(value) {
 86: 			fmt.Fprintf(runtime.Stderr, "error: Unsupported provider `%s`.\n", value)
 87: 			return int(output.Error)
 88: 		}
 89: 		patch.Provider = &provider
 90: 	}
 91: 	if value := strings.TrimSpace(*promptStyleFlag); value != "" {
 92: 		style := config.PromptStyle(value)
 93: 		if !config.IsPromptStyle(value) {
 94: 			fmt.Fprintf(runtime.Stderr, "error: Unsupported prompt style `%s`.\n", value)
 95: 			return int(output.Error)
 96: 		}
 97: 		patch.PromptStyle = &style
 98: 	}
 99: 	if value := strings.TrimSpace(*messageLanguageFlag); value != "" {
100: 		language := config.MessageLanguage(value)
101: 		if !config.IsMessageLanguage(value) {
102: 			fmt.Fprintf(runtime.Stderr, "error: Unsupported message language `%s`.\n", value)
103: 			return int(output.Error)
104: 		}
105: 		patch.MessageLanguage = &language
106: 	}
107: 	if value := strings.TrimSpace(*modelFlag); value != "" {
108: 		patch.Model = &value
109: 	}
110: 	if value := strings.TrimSpace(*baseURLFlag); value != "" {
111: 		patch.BaseURL = &value
112: 	}
113: 	if value := strings.TrimSpace(*standingInstructionFlag); value != "" {
114: 		patch.StandingInstruction = &value
115: 	}
116: 	if value := apiKeyInput; value != "" && *plaintextAPIKeyFlag {
117: 		patch.APIKey = &value
118: 	}
119: 
120: 	userConfig, err := config.LoadUserConfig(config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
121: 	if err != nil {
122: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
123: 		return int(output.Error)
124: 	}
125: 	merged := mergeConfigValues(userConfig, patch)
126: 	if apiKeyInput != "" && !*plaintextAPIKeyFlag {
127: 		merged.APIKey = nil
128: 	}
129: 	if merged.Provider == nil {
130: 		provider := config.DefaultProvider
131: 		merged.Provider = &provider
132: 	}
133: 	if merged.Model == nil {
134: 		model := config.GetDefaultModel(*merged.Provider)
135: 		merged.Model = &model
136: 	}
137: 	if merged.PromptStyle == nil {
138: 		style := config.DefaultPromptStyle
139: 		merged.PromptStyle = &style
140: 	}
141: 	if merged.MessageLanguage == nil {
142: 		language := config.DefaultMessageLanguage
143: 		merged.MessageLanguage = &language
144: 	}
145: 
146: 	effective := config.EffectiveConfig{
147: 		Provider:            *merged.Provider,
148: 		Model:               *merged.Model,
149: 		PromptStyle:         *merged.PromptStyle,
150: 		MessageLanguage:     *merged.MessageLanguage,
151: 		BaseURL:             merged.BaseURL,
152: 		StandingInstruction: merged.StandingInstruction,
153: 		APIKey:              merged.APIKey,
154: 		APIKeySource:        config.APIKeySourceMissing,
155: 	}
156: 	if merged.APIKey != nil {
157: 		effective.APIKeySource = config.APIKeySourcePlaintextConfig
158: 	}
159: 	var apiKeySave *config.SaveAPIKeyResult
160: 	if apiKeyInput != "" {
161: 		effective.APIKey = &apiKeyInput
162: 		if *plaintextAPIKeyFlag {
163: 			effective.APIKeySource = config.APIKeySourcePlaintextConfig
164: 			save := config.SaveAPIKeyResult{Provider: *merged.Provider, Source: config.APIKeySourcePlaintextConfig, Stored: true}
165: 			apiKeySave = &save
166: 		} else {
167: 			effective.APIKeySource = config.APIKeySourceSecretStore
168: 			save := config.SaveAPIKeyResult{Provider: *merged.Provider, Source: config.APIKeySourceSecretStore, Stored: false}
169: 			apiKeySave = &save
170: 		}
171: 	}
172: 	router := output.NewRouter(*jsonMode, runtime.Stdout, runtime.Stderr)
173: 	paths := config.GetConfigPaths(config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
174: 	if merged.APIKey != nil {
175: 		_ = router.WriteHuman(plaintextAPIKeyWarning, output.StderrTarget)
176: 	}
177: 	if *dryRun {
178: 		payload := map[string]any{
179: 			"command": "cnm init",
180: 			"config":  config.ToJSONConfigView(effective),
181: 			"dryRun":  true,
182: 			"ok":      true,
183: 			"path":    paths.UserConfigPath,
184: 			"status":  "dry_run",
185: 		}
186: 		if apiKeySave != nil {
187: 			payload["apiKeySave"] = apiKeySave
188: 		}
189: 		_ = router.WriteStructured(payload, "Dry-run: would initialize user config at "+paths.UserConfigPath+".", output.StdoutTarget)
190: 		return int(output.Success)
191: 	}
192: 
193: 	if apiKeyInput != "" && !*plaintextAPIKeyFlag {
194: 		save, err := config.SaveAPIKeyToSecretStore(*merged.Provider, apiKeyInput, runtime.SecretStore)
195: 		if err != nil {
196: 			fmt.Fprintf(runtime.Stderr, "error: %v Use --plaintext-api-key to store this key in user config instead.\n", err)
197: 			return int(output.Error)
198: 		}
199: 		if !save.Stored {
200: 			message := "Secret Store is not available; use --plaintext-api-key to store this key in user config."
201: 			if save.Warning != nil {
202: 				message = *save.Warning
203: 			}
204: 			fmt.Fprintf(runtime.Stderr, "error: %s\n", message)
205: 			return int(output.Error)
206: 		}
207: 		apiKeySave = &save
208: 	}
209: 
210: 	result, err := config.WriteUserConfig(merged, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
211: 	if err != nil {
212: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
213: 		return int(output.Error)
214: 	}
215: 	for _, warning := range result.Warnings {
216: 		_ = router.WriteHuman("Warning: "+warning, output.StderrTarget)
217: 	}
218: 	if router.IsJSON() {
219: 		payload := map[string]any{
220: 			"command": "cnm init",
221: 			"config":  config.ToJSONConfigView(effective),
222: 			"dryRun":  false,
223: 			"ok":      true,
224: 			"path":    result.Path,
225: 			"status":  "initialized",
226: 		}
227: 		if apiKeySave != nil {
228: 			payload["apiKeySave"] = apiKeySave
229: 		}
230: 		_ = router.WriteJSON(payload)
231: 		return int(output.Success)
232: 	}
233: 	fmt.Fprintf(runtime.Stdout, "Initialized user config at %s.\n", result.Path)
234: 	if apiKeySave != nil && apiKeySave.Source == config.APIKeySourceSecretStore {
235: 		fmt.Fprintf(runtime.Stdout, "Stored API key in Secret Store for %s.\n", apiKeySave.Provider)
236: 	}
237: 	for _, line := range config.ToHumanConfigLines(effective) {
238: 		fmt.Fprintln(runtime.Stdout, line)
239: 	}
240: 	return int(output.Success)
241: }
