243: func initHasExplicitConfigFlags(fs *flag.FlagSet) bool {
244: 	hasExplicit := false
245: 	fs.Visit(func(flag *flag.Flag) {
246: 		switch flag.Name {
247: 		case "provider", "model", "base-url", "prompt-style", "message-language", "standing-instruction", "api-key", "plaintext-api-key":
248: 			hasExplicit = true
249: 		}
250: 	})
251: 	return hasExplicit
252: }
