 4: 	"errors"
 5: 	"strings"
 6: 
 7: 	"github.com/zalando/go-keyring"
 8: )
 9: 
10: const defaultSecretStoreService = "commit-now-myfriend"
11: 
12: type SystemSecretStore struct {
13: 	Service string
14: }
15: 
16: func NewSystemSecretStore() SystemSecretStore {
17: 	return SystemSecretStore{Service: defaultSecretStoreService}
18: }
19: 
20: func (s SystemSecretStore) GetAPIKey(provider ProviderType) (*string, error) {
21: 	value, err := go_keyringGet(s.service(), secretStoreAccount(provider))
22: 	if err != nil {
23: 		if errors.Is(err, keyring.ErrNotFound) {
24: 			return nil, nil
25: 		}
26: 		// Reading credentials is optional during config resolution. A missing or
27: 		// unavailable platform store should behave like an absent key so commands
28: 		// can still report configuration state and fall back to env/plaintext config.
29: 		return nil, nil
30: 	}
31: 	if strings.TrimSpace(value) == "" {
32: 		return nil, nil
33: 	}
34: 	return &value, nil
35: }
36: 
37: func (s SystemSecretStore) SetAPIKey(provider ProviderType, apiKey string) error {
38: 	if strings.TrimSpace(apiKey) == "" {
39: 		return newError("Cannot store an empty API key for %s.", provider)
40: 	}
41: 	return go_keyringSet(s.service(), secretStoreAccount(provider), apiKey)
42: }
43: 
44: func (s SystemSecretStore) service() string {
45: 	if strings.TrimSpace(s.Service) != "" {
46: 		return s.Service
47: 	}
48: 	return defaultSecretStoreService
49: }
50: 
51: func secretStoreAccount(provider ProviderType) string {
52: 	return "cnm:" + string(provider)
53: }
54: 
55: var go_keyringGet = keyring.Get
56: var go_keyringSet = keyring.Set

